const esc = (s) => String(s).replace(/[&<>"']/g, (m) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#039;" }[m]));
const localPath = (lang, path = "") => `/${lang === "en" ? "" : `${lang}/`}${path}`.replace(/\/+/g, "/");
const canonical = (lang, path = "") => `${origin}${localPath(lang, path)}`;
const rel = (from, to) => to;
const titleFor = (lang, title) => `${title} | PikoBuy Sheet UK`;

function head(lang, title, description, path = "", type = "website") {
  const links = Object.keys(languages).map((code) => `<link rel="alternate" hreflang="${code}" href="${canonical(code, path)}">`).join("");
  return `<!doctype html><html lang="${lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="index,follow,max-image-preview:large"><title>${esc(titleFor(lang, title))}</title><meta name="description" content="${esc(description)}"><link rel="canonical" href="${canonical(lang, path)}">${links}<link rel="alternate" hreflang="x-default" href="${canonical("en", path)}"><meta property="og:type" content="${type}"><meta property="og:locale" content="${languages[lang].locale}"><meta property="og:title" content="${esc(titleFor(lang, title))}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${canonical(lang, path)}"><link rel="stylesheet" href="/assets/site.css"><script defer src="/assets/site.js"></script></head>`;
}

function header(lang, path = "") {
  const l = languages[lang];
  const links = [["", l.home], ["categories/", l.categories], ["product-details/", l.details], ["seo-articles/", l.articles], ["faq/", l.faq]];
  return `<body><header class="site-header"><div class="wrap nav-wrap"><a class="brand" href="${localPath(lang)}" aria-label="${esc(l.home)}"><span>PIKOBUY</span><small>SHEET UK</small></a><nav aria-label="Primary">${links.map(([href, label]) => `<a href="${localPath(lang, href)}"${path === href ? " aria-current=\"page\"" : ""}>${esc(label)}</a>`).join("")}</nav><form class="compact-search" action="${localPath(lang, "search/")}" method="get"><label class="sr-only" for="q">${esc(l.search)}</label><input id="q" name="q" placeholder="${esc(l.searchPlaceholder)}"><button>${esc(l.search)}</button></form><details class="language"><summary>${esc(l.name)}</summary><div>${Object.entries(languages).map(([code, item]) => `<a hreflang="${code}" lang="${code}" href="${localPath(code, path)}"${code === lang ? " aria-current=\"true\"" : ""}>${esc(item.name)}</a>`).join("")}</div></details></div></header><main>`;
}

function footer(lang) { const l = languages[lang]; return `</main><footer><div class="wrap"><strong>PIKOBUY SHEET UK</strong><p>${esc(l.footer)}</p><p class="small">${esc(l.disclaimer)}</p></div></footer></body></html>`; }
function jsonLd(data) { return `<script type="application/ld+json">${JSON.stringify(data)}</script>`; }

function guideBody(lang, guide) {
  const x = articleText[lang];
  const topic = x[guide.topic];
  const p = [topic[0], topic[1], x.framework[0], x.framework[1], x.framework[2], x.framework[3]];
  return `<article class="article"><p class="eyebrow">${esc(guide.keyword)} · ${date}</p><h1>${esc(guide.titles[lang])}</h1><p class="deck">${esc(topic[0])}</p>${x.headings.map((heading, index) => `<section><h2>${esc(heading)}</h2><p>${esc(p[index])}</p>${index < 4 ? `<p>${esc(x.framework[(index + 1) % x.framework.length])}</p>` : ""}</section>`).join("")}<aside class="fact-note"><strong>${esc(languages[lang].independent)}</strong><p>${esc(languages[lang].source)}</p></aside><p class="source">${esc(languages[lang].disclaimer)}</p></article>`;
}

function home(lang) {
  const l = languages[lang];
  const x = articleText[lang];
  const guideCards = Object.entries(guideData).map(([slug, guide]) => `<a class="guide-card" href="${localPath(lang, `guides/${slug}/`)}"><span>${esc(guide.keyword)}</span><h3>${esc(guide.titles[lang])}</h3><p>${esc(articleText[lang][guide.topic][0])}</p><b>→</b></a>`).join("");
  const html = `${head(lang, l.hero, l.lead)}${header(lang)}<section class="hero"><div class="wrap"><p class="eyebrow">${esc(l.kicker)}</p><h1>${esc(l.hero)}</h1><p>${esc(l.lead)}</p><div class="actions"><a class="button" href="${localPath(lang, "categories/")}">${esc(l.browse)}</a><a class="button ghost" href="${localPath(lang, "seo-articles/")}">${esc(l.read)}</a></div></div></section><section class="wrap intro"><p class="eyebrow">${esc(l.independent)}</p><h2>${esc(l.cta)}</h2><p>${esc(l.disclaimer)}</p></section><section class="wrap"><div class="section-heading"><p class="eyebrow">${esc(l.articles)}</p><h2>${esc(l.articles)}</h2></div><div class="guide-grid">${guideCards}</div></section><section class="wrap steps"><div><b>01</b><h3>${esc(x.headings[0])}</h3><p>${esc(x.framework[0])}</p></div><div><b>02</b><h3>${esc(x.headings[1])}</h3><p>${esc(x.framework[1])}</p></div><div><b>03</b><h3>${esc(x.headings[2])}</h3><p>${esc(x.framework[2])}</p></div></section>${footer(lang)}`;
  return html;
}

function categories(lang) {
  const l = languages[lang];
  const cards = categoryNames[lang].map((name, i) => `<a class="category-card" href="${localPath(lang, `product-details/?category=${encodeURIComponent(name.toLowerCase())}`)}"><span>0${i + 1}</span><h2>${esc(name)}</h2><p>${esc(l.cta)}</p></a>`).join("");
  return `${head(lang, `${l.categories} | PikoBuy spreadsheet`, l.lead, "categories/")}${header(lang, "categories/")}<section class="page-title wrap"><p class="eyebrow">PikoBuy spreadsheet categories</p><h1>${esc(l.categories)}</h1><p>${esc(l.lead)}</p></section><section class="wrap category-grid">${cards}</section>${footer(lang)}`;
}

function details(lang) {
  const l = languages[lang];
  const x = articleText[lang];
  return `${head(lang, `${l.details} | PikoBuy spreadsheet`, l.lead, "product-details/")}${header(lang, "product-details/")}<section class="page-title wrap"><p class="eyebrow">${esc(l.kicker)}</p><h1>${esc(l.details)}</h1><p>${esc(l.lead)}</p></section><section class="wrap checklist">${x.headings.slice(0, 4).map((heading, index) => `<article><span>0${index + 1}</span><h2>${esc(heading)}</h2><p>${esc(x.framework[index])}</p></article>`).join("")}</section>${footer(lang)}`;
}

function articles(lang) {
  const l = languages[lang];
  const cards = Object.entries(guideData).map(([slug, guide]) => `<article class="article-list"><p>${esc(guide.keyword)}</p><h2><a href="${localPath(lang, `guides/${slug}/`)}">${esc(guide.titles[lang])}</a></h2><p>${esc(articleText[lang][guide.topic][0])}</p><a class="text-link" href="${localPath(lang, `guides/${slug}/`)}">${esc(l.read)} →</a></article>`).join("");
  return `${head(lang, `${l.articles} | PikoBuy spreadsheet`, l.lead, "seo-articles/")}${header(lang, "seo-articles/")}<section class="page-title wrap"><p class="eyebrow">PikoBuy spreadsheet · QC · shipping · returns</p><h1>${esc(l.articles)}</h1><p>${esc(l.lead)}</p></section><section class="wrap article-list-grid">${cards}</section>${footer(lang)}`;
}

function faq(lang) {
  const l = languages[lang];
  const x = articleText[lang];
  const faqs = faqQuestions[lang].map((q, index) => [q, [l.disclaimer, x.qc[0], x.returns[0], x.returns[1], x.framework[3]][index]]);
  const faqHtml = faqs.map(([q, a]) => `<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join("");
  const schema = { "@context": "https://schema.org", "@type": "FAQPage", mainEntity: faqs.map(([name, text]) => ({ "@type": "Question", name, acceptedAnswer: { "@type": "Answer", text } })) };
  return `${head(lang, `PikoBuy spreadsheet ${l.faq}`, l.lead, "faq/")}${jsonLd(schema)}${header(lang, "faq/")}<section class="page-title wrap"><p class="eyebrow">Independent answers</p><h1>${esc(l.faq)}</h1><p>${esc(l.disclaimer)}</p></section><section class="wrap faq">${faqHtml}</section>${footer(lang)}`;
}

function search(lang) {
  const l = languages[lang];
  return `${head(lang, `${l.search} | PikoBuy Sheet UK`, l.searchLead, "search/")}${header(lang)}<section class="page-title wrap"><p class="eyebrow">${esc(l.search)}</p><h1>${esc(l.search)}</h1><p>${esc(l.searchLead)}</p><form class="big-search" action="${localPath(lang, "search/")}" method="get"><input name="q" placeholder="${esc(l.searchPlaceholder)}"><button class="button">${esc(l.search)}</button></form></section><section class="wrap" id="search-results" data-empty="${esc(l.noResults)}"></section>${footer(lang)}`;
}

